		}
		if value == nil {
			return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
		}
		labels[key] = *value
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return nil, fmt.Errorf("decode labels: %w", err)
	}
