	for dec.More() {
		keyToken, err := dec.Token()
		if err != nil {
			return Event{}, fmt.Errorf("decode events array: %w", err)
		}
		key, ok := keyToken.(string)
		if !ok {
			return Event{}, fmt.Errorf("decode events array: event field names must be strings")
		}
