1	package logfile
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"hash/crc32"
8		"os"
9		"path/filepath"
10		"sync"
11	)
12	
13	const (
14		headerSize = 8
15		// maxPayload guards against absurd allocations when a corrupt length
16		// prefix happens to point inside the file.
17		maxPayload = 64 << 20
18	)
19	
20	// ErrPoisoned is returned after a write or sync failure. The log refuses all
21	// further writes until the process is restarted and recovery succeeds.
22	var ErrPoisoned = errors.New("log is unavailable after a storage failure")
23	
24	// CorruptionError marks a complete frame that fails its checksum or contains
25	// illegal data, as opposed to an incomplete trailing frame.
26	type CorruptionError struct{ Reason string }
27	
28	func (e *CorruptionError) Error() string { return e.Reason }
29	
30	func corruption(format string, args ...any) error {
31		return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
32	}
33	
34	// frameLog is the shared append-only frame writer behind the event, incident,
35	// and metric logs. It owns the frame layout, torn-tail recovery, and the
36	// poison-on-failure write path; each concrete log supplies only its own
37	// payload encoding and content validation, so the durability rule lives in
38	// exactly one place.
39	type frameLog struct {
40		mu       sync.Mutex
41		file     *os.File
42		dir      string
43		noun     string // the log's name in error messages: "event", "incident", "metrics"
44		unit     string // what one frame holds: "batch", "incident record", "metric batch"
45		poisoned bool
46	}
47	
48	// openFrameLog opens (creating if absent) the named log inside an
49	// already-locked data directory, replays its frames with decode, and
50	// truncates at most one incomplete trailing frame. A corrupt frame in the
51	// middle, or a complete frame whose payload decode rejects, is fatal and
52	// leaves the file untouched.
53	func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error)) (*frameLog, []T, error) {
54		path := filepath.Join(dir, name)
55		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
56		if err != nil {
57			return nil, nil, fmt.Errorf("open %s log: %w", noun, err)
58		}
59	
60		items, validLen, err := replayFrames(file, noun, decode)
61		if err != nil {
62			file.Close()
63			return nil, nil, err
64		}
65		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
66			// Drop exactly one incomplete trailing frame; the only mutation
67			// recovery performs, fsynced before serving.
68			if err := file.Truncate(validLen); err != nil {
69				file.Close()
70				return nil, nil, fmt.Errorf("truncate incomplete trailing %s frame: %w", noun, err)
71			}
72			if err := file.Sync(); err != nil {
73				file.Close()
74				return nil, nil, fmt.Errorf("sync %s log: %w", noun, err)
75			}
76		}
77		// Flush the directory so the log file's own entry is durable, whether it
78		// was just created or just truncated.
79		if err := syncDir(dir); err != nil {
80			file.Close()
81			return nil, nil, fmt.Errorf("sync data directory: %w", err)
82		}
83	
84		return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, nil
85	}
86	
87	// replayFrames scans the log and returns the decoded frames and the byte
88	// offset at which the log is known good. A torn trailing frame — a partial
89	// header, or a header whose payload never fully landed — ends the scan
90	// without error; any corruption before that offset is fatal.
91	func replayFrames[T any](file *os.File, noun string, decode func(payload []byte) (T, error)) ([]T, int64, error) {
92		data, err := os.ReadFile(file.Name())
93		if err != nil {
94			return nil, 0, fmt.Errorf("read %s log: %w", noun, err)
95		}
96	
97		var items []T
98		pos := int64(0)
99		for pos < int64(len(data)) {
100			remaining := int64(len(data)) - pos
101			if remaining < headerSize {
102				break // torn partial header
103			}
104			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
105			if payloadLen <= 0 || payloadLen > maxPayload {
106				return nil, 0, corruption("corrupt %s frame header at offset %d", noun, pos)
107			}
108			frameEnd := pos + headerSize + payloadLen
109			if frameEnd > int64(len(data)) {
110				break // header landed but its payload did not: torn tail
111			}
112			payload := data[pos+headerSize : frameEnd]
113			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
114			if crc32.ChecksumIEEE(payload) != wantCRC {
115				return nil, 0, corruption("%s checksum mismatch at offset %d", noun, pos)
116			}
117			item, err := decode(payload)
118			if err != nil {
119				return nil, 0, corruption("illegal %s frame payload at offset %d: %v", noun, pos, err)
120			}
121			items = append(items, item)
122			pos = frameEnd
123		}
124		return items, pos, nil
125	}
126	
127	// appendFrame durably writes one already-encoded payload: the frame is
128	// written and fsynced before the call returns. Any write or sync failure
129	// poisons the log, so this call and every later one fail until restart. A
130	// payload that fails the size check is rejected before the log is touched
131	// and does not poison it.
132	func (l *frameLog) appendFrame(payload []byte) (err error) {
133		if len(payload) > maxPayload {
134			return fmt.Errorf("%s exceeds %d byte frame limit", l.unit, maxPayload)
135		}
136	
137		frame := make([]byte, headerSize+len(payload))
138		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
139		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
140		copy(frame[headerSize:], payload)
141	
142		l.mu.Lock()
143		defer l.mu.Unlock()
144		if l.poisoned {
145			return ErrPoisoned
146		}
147		defer func() {
148			if err != nil {
149				l.poisoned = true
150			}
151		}()
152	
153		if _, err = l.file.Write(frame); err != nil {
154			return fmt.Errorf("write %s log: %w", l.noun, err)
155		}
156		if err = l.file.Sync(); err != nil {
157			return fmt.Errorf("sync %s log: %w", l.noun, err)
158		}
159		return nil
160	}
161	
162	// Poisoned reports whether the log has suffered an unrecoverable write error.
163	func (l *frameLog) Poisoned() bool {
164		l.mu.Lock()
165		defer l.mu.Unlock()
166		return l.poisoned
167	}
168	
169	// Close releases the log file.
170	func (l *frameLog) Close() error {
171		l.mu.Lock()
172		defer l.mu.Unlock()
173		return l.file.Close()
174	}
