1	package events
2	
3	import (
4		"maps"
5		"sort"
6		"strings"
7		"sync"
8		"time"
9	)
10	
11	// BeforeCommit persists a batch of brand-new events. It runs while the
12	// timeline lock is held and before the batch becomes visible to queries, so a
13	// successful return guarantees the batch is durable and committed atomically.
14	// Returning an error rejects the batch without touching the timeline.
15	type BeforeCommit func(persisted []Event) error
16	
17	// Timeline is a concurrency-safe, de-duplicated event timeline that accepts
18	// whole batches and reports replays of already-stored events.
19	type Timeline struct {
20		mu     sync.RWMutex
21		byID   map[string]Event
22		events []Event
23	}
24	
25	// NewTimeline returns an empty timeline.
26	func NewTimeline() *Timeline {
27		return &Timeline{byID: make(map[string]Event)}
28	}
29	
30	// IngestResult counts how a batch was applied: Created events are new,
31	// Replayed events matched an existing event with the same id and content.
32	type IngestResult struct {
33		Created  int
34		Replayed int
35	}
36	
37	// Ingest normalizes and validates every event first, then checks the whole
38	// batch against existing events and itself. Validation failures produce a
39	// ValidationError; duplicate ids with differing content, or a repeated id
40	// within the batch, produce a ConflictError. Nothing is stored when an error
41	// is returned.
42	//
43	// New events are passed to beforeCommit for durable storage; only after it
44	// succeeds does the batch become visible, so concurrent readers see either
45	// the complete batch or none of it.
46	func (t *Timeline) Ingest(batch []Event, beforeCommit BeforeCommit) (IngestResult, error) {
47		normalized := make([]Event, len(batch))
48		for i, event := range batch {
49			norm, err := Normalize(event)
50			if err != nil {
51				return IngestResult{}, err
52			}
53			normalized[i] = norm
54		}
55	
56		t.mu.Lock()
57		defer t.mu.Unlock()
58	
59		pending := make(map[string]struct{}, len(normalized))
60		var created []Event
61		var result IngestResult
62		for _, event := range normalized {
63			if _, repeated := pending[event.ID]; repeated {
64				return IngestResult{}, &ConflictError{Reason: "event id repeats within batch"}
65			}
66			pending[event.ID] = struct{}{}
67			if existing, ok := t.byID[event.ID]; ok {
68				if !sameEvent(existing, event) {
69					return IngestResult{}, &ConflictError{Reason: "event id already exists with different content"}
70				}
71				result.Replayed++
72				continue
73			}
74			created = append(created, event)
75			result.Created++
76		}
77	
78		if len(created) > 0 {
79			if beforeCommit != nil {
80				if err := beforeCommit(created); err != nil {
81					return IngestResult{}, err
82				}
83			}
84			for _, event := range created {
85				t.byID[event.ID] = event
86				t.events = append(t.events, event)
87			}
88			sort.SliceStable(t.events, func(i, j int) bool {
89				return byTimeThenID(t.events[i], t.events[j])
90			})
91		}
92		return result, nil
93	}
94	
95	// Load inserts events recovered from durable storage during startup. Every
96	// event must already be normalized; a duplicate id with differing content is
97	// reported as a conflict so the caller can fail rather than mutate data.
98	func (t *Timeline) Load(event Event) error {
99		if _, err := Normalize(event); err != nil {
100			return err
101		}
102		t.mu.Lock()
103		defer t.mu.Unlock()
104		if existing, ok := t.byID[event.ID]; ok {
105			if !sameEvent(existing, event) {
106				return &ConflictError{Reason: "event id already exists with different content"}
107			}
108			return nil
109		}
110		t.byID[event.ID] = event
111		t.events = append(t.events, event)
112		return nil
113	}
114	
115	// SortAll orders recovered events by time, then id. Call it once after Load.
116	func (t *Timeline) SortAll() {
117		t.mu.Lock()
118		defer t.mu.Unlock()
119		sort.SliceStable(t.events, func(i, j int) bool {
120			return byTimeThenID(t.events[i], t.events[j])
121		})
122	}
123	
124	// withinBounds reports whether at falls in the inclusive [Since, Until]
125	// range. A nil bound means unbounded in that direction, so an explicit
126	// boundary at the zero instant is still applied. Comparisons use absolute
127	// instants, so time zone spellings of the same moment agree.
128	func (q Query) withinBounds(at time.Time) bool {
129		if q.Since != nil && at.Before(*q.Since) {
130			return false
131		}
132		if q.Until != nil && at.After(*q.Until) {
133			return false
134		}
135		return true
136	}
137	
138	// Query returns the events matching the optional filters, ordered by time and
139	// then by id. Time equality uses absolute instants.
140	func (t *Timeline) Query(query Query) []Event {
141		service := strings.TrimSpace(query.Service)
142		severity := strings.ToLower(strings.TrimSpace(query.Severity))
143	
144		t.mu.RLock()
145		defer t.mu.RUnlock()
146		result := make([]Event, 0, len(t.events))
147		for _, event := range t.events {
148			if service != "" && event.Service != service {
149				continue
150			}
151			if severity != "" && event.Severity != severity {
152				continue
153			}
154			if !query.withinBounds(event.At) {
155				continue
156			}
157			if !labelsMatch(event.Labels, query.Labels) {
158				continue
159			}
160			result = append(result, event)
161		}
162		return result
163	}
164	
165	// SnapshotIDs returns the ids of events matching the optional filters, in
166	// time-then-id order. The set is taken under the timeline lock, so a batch
167	// committed concurrently is either fully present or fully absent; events
168	// added after the call never appear in the returned set, which makes it
169	// suitable for stable pagination across later writes.
170	func (t *Timeline) SnapshotIDs(query Query) []string {
171		service := strings.TrimSpace(query.Service)
172		severity := strings.ToLower(strings.TrimSpace(query.Severity))
173	
174		t.mu.RLock()
175		defer t.mu.RUnlock()
176		ids := make([]string, 0, len(t.events))
177		for _, event := range t.events {
178			if service != "" && event.Service != service {
179				continue
180			}
181			if severity != "" && event.Severity != severity {
182				continue
183			}
184			if !query.withinBounds(event.At) {
185				continue
186			}
187			if !labelsMatch(event.Labels, query.Labels) {
188				continue
189			}
190			ids = append(ids, event.ID)
191		}
192		return ids
193	}
194	
195	// LookupEvent returns the service of a stored event, or ok=false when the id
196	// is unknown. It never mutates the timeline, which lets incident handling
197	// link events without changing them.
198	func (t *Timeline) LookupEvent(id string) (service string, ok bool) {
199		t.mu.RLock()
200		defer t.mu.RUnlock()
201		event, found := t.byID[id]
202		if !found {
203			return "", false
204		}
205		return event.Service, true
206	}
207	
208	// EventsByID returns the events for ids in the requested order. Every id
209	// must refer to a stored event; events are never removed, so a set captured
210	// by SnapshotIDs stays resolvable. Missing ids are skipped only when the
211	// caller passes ids not produced by SnapshotIDs.
212	func (t *Timeline) EventsByID(ids []string) []Event {
213		t.mu.RLock()
214		defer t.mu.RUnlock()
215		out := make([]Event, 0, len(ids))
216		for _, id := range ids {
217			if event, ok := t.byID[id]; ok {
218				out = append(out, event)
219			}
220		}
221		return out
222	}
223	
224	// sameEvent compares two normalized events on their absolute instant and
225	// their labels. Normalized label sets are nil when empty, so the three "no
226	// labels" spellings compare equal, and map comparison makes key order and
227	// original whitespace irrelevant.
228	func sameEvent(a, b Event) bool {
229		return a.ID == b.ID &&
230			a.Service == b.Service &&
231			a.Severity == b.Severity &&
232			a.Message == b.Message &&
233			a.At.Equal(b.At) &&
234			maps.Equal(a.Labels, b.Labels)
235	}
