1	package main
2	
3	import (
4		"context"
5		"errors"
6		"flag"
7		"fmt"
8		"net"
9		"net/http"
10		"os"
11		"os/signal"
12		"syscall"
13		"time"
14	
15		"github.com/cocosolocoder/signalroom/internal/events"
16		"github.com/cocosolocoder/signalroom/internal/httpapi"
17		"github.com/cocosolocoder/signalroom/internal/incidents"
18		"github.com/cocosolocoder/signalroom/internal/logfile"
19		"github.com/cocosolocoder/signalroom/internal/metrics"
20	)
21	
22	func runServe(args []string) error {
23		fs := flag.NewFlagSet("serve", flag.ContinueOnError)
24		addr := fs.String("addr", ":8080", "listen address")
25		dataDir := fs.String("data", "", "directory for durable event data")
26		if err := fs.Parse(args); err != nil {
27			return err
28		}
29		if *dataDir == "" || fs.NArg() != 0 {
30			fmt.Fprintln(os.Stderr, "usage: signalroom serve --addr <address> --data <directory>")
31			os.Exit(2)
32		}
33	
34		log, batches, err := logfile.Open(*dataDir)
35		if err != nil {
36			return err
37		}
38		defer log.Close()
39	
40		timeline := events.NewTimeline()
41		for _, batch := range batches {
42			for _, event := range batch {
43				if err := timeline.Load(event); err != nil {
44					return fmt.Errorf("recover events: %w", err)
45				}
46			}
47		}
48		timeline.SortAll()
49	
50		// Incidents are replayed after events so linked event ids resolve
51		// against the already-recovered timeline.
52		incidentLog, incidentRecords, err := logfile.OpenIncidentLog(*dataDir)
53		if err != nil {
54			return err
55		}
56		defer incidentLog.Close()
57	
58		registry := incidents.NewRegistry(timeline, incidentLog.AppendRecord)
59		for _, record := range incidentRecords {
60			if err := registry.Load(record); err != nil {
61				return fmt.Errorf("recover incidents: %w", err)
62			}
63		}
64	
65		// Metric samples live in their own log and recover independently of
66		// events and incidents.
67		metricLog, metricBatches, err := logfile.OpenMetricsLog(*dataDir)
68		if err != nil {
69			return err
70		}
71		defer metricLog.Close()
72	
73		metricStore := metrics.NewStore()
74		for _, batch := range metricBatches {
75			for _, sample := range batch {
76				if err := metricStore.Load(sample); err != nil {
77					return fmt.Errorf("recover metrics: %w", err)
78				}
79			}
80		}
81	
82		listener, err := net.Listen("tcp", *addr)
83		if err != nil {
84			return fmt.Errorf("listen on %s: %w", *addr, err)
85		}
86	
87		server := &http.Server{
88			Handler: httpapi.NewHandler(timeline, log, log,
89				httpapi.WithIncidents(registry, incidentLog),
90				httpapi.WithMetrics(metricStore, metricLog)),
91			ReadHeaderTimeout: 10 * time.Second,
92		}
93		serverErr := make(chan error, 1)
94		go func() {
95			serverErr <- server.Serve(listener)
96		}()
97	
98		// Published exactly once the socket accepts connections; clients (and
99		// tests) can wait on this line instead of polling with fixed sleeps.
100		fmt.Printf("signalroom: listening on %s\n", listener.Addr())
101	
102		stop := make(chan os.Signal, 1)
103		signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
104		select {
105		case sig := <-stop:
106			fmt.Fprintf(os.Stderr, "signalroom: received %s, shutting down\n", sig)
107		case err := <-serverErr:
108			if !errors.Is(err, http.ErrServerClosed) {
109				return fmt.Errorf("serve: %w", err)
110			}
111		}
112	
113		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
114		defer cancel()
115		if err := server.Shutdown(shutdownCtx); err != nil {
