package logfile

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sync"
)

const (
	headerSize = 8
	// maxPayload guards against absurd allocations when a corrupt length
	// prefix happens to point inside the file.
	maxPayload = 64 << 20
)

// ErrPoisoned is returned after a write or sync failure. The log refuses all
// further writes until the process is restarted and recovery succeeds.
var ErrPoisoned = errors.New("log is unavailable after a storage failure")

// OversizeError reports a payload that exceeds the frame payload limit. It
// marks a content-size problem in the submitted batch, not a storage
// failure: the log is left untouched and stays usable for later writes
// within the limit.
type OversizeError struct {
	Unit  string // what one frame holds, e.g. "batch"
	Size  int    // encoded payload bytes
	Limit int    // maximum payload bytes per frame
}

func (e *OversizeError) Error() string {
	return fmt.Sprintf("%s of %d bytes exceeds the %d byte storage capacity", e.Unit, e.Size, e.Limit)
}

// IsOversize reports whether err is an OversizeError.
func IsOversize(err error) bool {
	var target *OversizeError
	return errors.As(err, &target)
}

// CorruptionError marks a complete frame that fails its checksum or contains
// illegal data, as opposed to an incomplete trailing frame.
type CorruptionError struct{ Reason string }

func (e *CorruptionError) Error() string { return e.Reason }

func corruption(format string, args ...any) error {
	return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
}

// frameLog is the shared append-only frame writer behind the event, incident,
// and metric logs. It owns the frame layout, torn-tail recovery, and the
// poison-on-failure write path; each concrete log supplies only its own
// payload encoding and content validation, so the durability rule lives in
// exactly one place.
type frameLog struct {
	mu       sync.Mutex
	file     *os.File
	dir      string
	noun     string // the log's name in error messages: "event", "incident", "metrics"
	unit     string // what one frame holds: "batch", "incident record", "metric batch"
	poisoned bool
}

// openFrameLog opens (creating if absent) the named log inside an
// already-locked data directory, replays its frames with decode, and
// truncates at most one incomplete trailing frame. A corrupt frame in the
// middle, or a complete frame whose payload decode rejects, is fatal and
// leaves the file untouched.
func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error)) (*frameLog, []T, error) {
	path := filepath.Join(dir, name)
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, nil, fmt.Errorf("open %s log: %w", noun, err)
	}

	items, validLen, err := replayFrames(file, noun, decode)
	if err != nil {
		file.Close()
		return nil, nil, err
	}
	if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
		// Drop exactly one incomplete trailing frame; the only mutation
		// recovery performs, fsynced before serving.
		if err := file.Truncate(validLen); err != nil {
			file.Close()
			return nil, nil, fmt.Errorf("truncate incomplete trailing %s frame: %w", noun, err)
		}
		if err := file.Sync(); err != nil {
			file.Close()
			return nil, nil, fmt.Errorf("sync %s log: %w", noun, err)
		}
	}
	// Flush the directory so the log file's own entry is durable, whether it
	// was just created or just truncated.
	if err := syncDir(dir); err != nil {
		file.Close()
		return nil, nil, fmt.Errorf("sync data directory: %w", err)
	}

	return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, nil
}

// replayFrames scans the log and returns the decoded frames and the byte
// offset at which the log is known good. A torn trailing frame — a partial
// header, or a header whose payload never fully landed — ends the scan
// without error; any corruption before that offset is fatal.
func replayFrames[T any](file *os.File, noun string, decode func(payload []byte) (T, error)) ([]T, int64, error) {
	data, err := os.ReadFile(file.Name())
	if err != nil {
		return nil, 0, fmt.Errorf("read %s log: %w", noun, err)
	}

	var items []T
	pos := int64(0)
	for pos < int64(len(data)) {
		remaining := int64(len(data)) - pos
		if remaining < headerSize {
			break // torn partial header
		}
		payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
		if payloadLen <= 0 || payloadLen > maxPayload {
			return nil, 0, corruption("corrupt %s frame header at offset %d", noun, pos)
		}
		frameEnd := pos + headerSize + payloadLen
		if frameEnd > int64(len(data)) {
			break // header landed but its payload did not: torn tail
		}
		payload := data[pos+headerSize : frameEnd]
		wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
		if crc32.ChecksumIEEE(payload) != wantCRC {
			return nil, 0, corruption("%s checksum mismatch at offset %d", noun, pos)
		}
		item, err := decode(payload)
		if err != nil {
			return nil, 0, corruption("illegal %s frame payload at offset %d: %v", noun, pos, err)
		}
		items = append(items, item)
		pos = frameEnd
	}
	return items, pos, nil
}

// appendFrame durably writes one already-encoded payload: the frame is
// written and fsynced before the call returns. Any write or sync failure
// poisons the log, so this call and every later one fail until restart. A
// payload that fails the size check is rejected before the log is touched
// and does not poison it.
func (l *frameLog) appendFrame(payload []byte) (err error) {
	if len(payload) > maxPayload {
		return fmt.Errorf("%s exceeds %d byte frame limit", l.unit, maxPayload)
	}

	frame := make([]byte, headerSize+len(payload))
	binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
	binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
	copy(frame[headerSize:], payload)

	l.mu.Lock()
	defer l.mu.Unlock()
	if l.poisoned {
		return ErrPoisoned
	}
	defer func() {
		if err != nil {
			l.poisoned = true
		}
	}()

	if _, err = l.file.Write(frame); err != nil {
		return fmt.Errorf("write %s log: %w", l.noun, err)
	}
	if err = l.file.Sync(); err != nil {
		return fmt.Errorf("sync %s log: %w", l.noun, err)
	}
	return nil
}

// Poisoned reports whether the log has suffered an unrecoverable write error.
func (l *frameLog) Poisoned() bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.poisoned
}

// Close releases the log file.
func (l *frameLog) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.file.Close()
}

// Package httpapi exposes the event timeline over HTTP.
package httpapi

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
	"github.com/cocosolocoder/signalroom/internal/incidents"
	"github.com/cocosolocoder/signalroom/internal/metrics"
)

// maxBodyBytes bounds a single POST request body.
const maxBodyBytes = 16 << 20

// Storage durably persists a batch before it becomes visible.
type Storage interface {
	Append(batch []events.Event) error
	Poisoned() bool
}

type envelope struct {
	Events json.RawMessage `json:"events"`
}

// allowedEnvelopeFields is the exact set of members a POST /events body may
// carry.
var allowedEnvelopeFields = map[string]struct{}{
	"events": {},
}

// Handler wires the timeline, its durable log, and the cursor store to HTTP
// routes.
type Handler struct {
	timeline *events.Timeline
	log      Storage
	cursors  CursorStore

	incidents    *incidents.Registry
	incidentLogs IncidentStorage

	metrics    *metrics.Store
	metricLogs MetricStorage

	mux *http.ServeMux
}

// Option customizes a Handler at construction.
type Option func(*Handler)

// WithIncidents enables the incident endpoints, backed by reg and its
// durable store.
func WithIncidents(reg *incidents.Registry, store IncidentStorage) Option {
	return func(h *Handler) {
		h.incidents = reg
		h.incidentLogs = store
	}
}

// WithMetrics enables the metric endpoints, backed by store and its durable
// log.
func WithMetrics(store *metrics.Store, log MetricStorage) Option {
	return func(h *Handler) {
		h.metrics = store
		h.metricLogs = log
	}
}

// NewHandler builds the HTTP handler for a timeline backed by log. cursors
// supplies the per-directory signing key and snapshot storage for paging.
func NewHandler(timeline *events.Timeline, log Storage, cursors CursorStore, opts ...Option) *Handler {
	h := &Handler{timeline: timeline, log: log, cursors: cursors, mux: http.NewServeMux()}
	for _, opt := range opts {
		opt(h)
	}
	h.mux.HandleFunc("/events", h.events)
	h.mux.HandleFunc("/alerts/preview", h.previewAlerts)
	h.mux.HandleFunc("/events/compare", h.compareEvents)
	h.mux.HandleFunc("/events/page", h.pageEvents)
	if h.metrics != nil {
		h.mux.HandleFunc("/metrics", h.metricsRoot)
		h.mux.HandleFunc("/metrics/aggregate", h.metricsAggregate)
	}
	if h.incidents != nil {
		h.mux.HandleFunc("/incidents", h.incidentsRoot)
		h.mux.HandleFunc("/incidents/{id}", h.incidentItem)
		h.mux.HandleFunc("/incidents/{id}/actions", h.incidentActions)
	}
	h.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		writeError(w, http.StatusNotFound, "not found")
	})
	return h
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.mux.ServeHTTP(w, r)
}

func (h *Handler) unavailable() bool {
	return h.log.Poisoned()
}

func (h *Handler) events(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodPost:
		h.postEvents(w, r)
	case http.MethodGet:
		h.getEvents(w, r)
	default:
		w.Header().Set("Allow", "GET, POST")
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
	}
}

func (h *Handler) postEvents(w http.ResponseWriter, r *http.Request) {
	if h.unavailable() {
		writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
		return
	}

	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}

	fields, err := decodeStrictObject(body, allowedEnvelopeFields)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}
	input := envelope{Events: fields["events"]}
	if len(bytes.TrimSpace(input.Events)) == 0 {
		writeError(w, http.StatusBadRequest, "events must be a non-empty array")
		return
	}

	batch, err := events.DecodeBatch(input.Events)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid events array")
		return
	}
	if len(batch) == 0 {
		writeError(w, http.StatusBadRequest, "events must not be empty")
		return
	}

	result, err := h.timeline.Ingest(batch, h.log.Append)
	if err != nil {
		switch {
		case events.IsValidationError(err):
			writeError(w, http.StatusBadRequest, err.Error())
		case events.IsConflictError(err):
			writeError(w, http.StatusConflict, err.Error())
		default:
			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]int{
		"created":  result.Created,
		"replayed": result.Replayed,
	})
}

func (h *Handler) getEvents(w http.ResponseWriter, r *http.Request) {
	if h.unavailable() {
		writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
		return
	}

	values := r.URL.Query()
	labels, err := events.ParseLabelConditions(values["label"])
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	query := events.Query{
		Service:  values.Get("service"),
		Severity: values.Get("severity"),
		Labels:   labels,
	}
	if raw := values.Get("since"); raw != "" {
		parsed, err := time.Parse(time.RFC3339Nano, raw)
		if err != nil {
			writeError(w, http.StatusBadRequest, "since must be an RFC3339Nano timestamp")
			return
		}
		query.Since = &parsed
	}
	if raw := values.Get("until"); raw != "" {
		parsed, err := time.Parse(time.RFC3339Nano, raw)
		if err != nil {
			writeError(w, http.StatusBadRequest, "until must be an RFC3339Nano timestamp")
			return
		}
		query.Until = &parsed
	}
	if query.Since != nil && query.Until != nil && query.Since.After(*query.Until) {
		writeError(w, http.StatusBadRequest, "since must not be after until")
		return
	}

	found := h.timeline.Query(query)
	writeEvents(w, found)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

func writeJSON(w http.ResponseWriter, status int, payload any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	_ = enc.Encode(payload)
}

func writeEvents(w http.ResponseWriter, found []events.Event) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	if len(found) == 0 {
		_, _ = w.Write([]byte("[]\n"))
		return
	}
	if err := json.NewEncoder(w).Encode(eventsToDTOs(found)); err != nil {
		return
	}
}

type eventDTO struct {
	ID       string            `json:"id"`
	Service  string            `json:"service"`
	Severity string            `json:"severity"`
	Message  string            `json:"message"`
	At       time.Time         `json:"at"`
	Labels   map[string]string `json:"labels,omitempty"`
}

func eventsToDTOs(found []events.Event) []eventDTO {
	dtos := make([]eventDTO, len(found))
	for i, event := range found {
		dtos[i] = eventDTO{
			ID:       event.ID,
			Service:  event.Service,
			Severity: event.Severity,
			Message:  event.Message,
			At:       event.At,
			Labels:   event.Labels,
		}
	}
	return dtos
}

